#include <map>
#include <print>
#include <string>

int main() {
    std::map<std::string, int> scores;
    scores["小明"] = 88;
    std::println("size = {}", scores.size());
    if (scores.contains("小明"))                        // 先问有没有
        std::println("小明的分数: {}", scores.at("小明"));   // 确认了再取
    std::println("新同学 = {}", scores["新同学"]);      // 方括号：凭空造出来，返回 0
    std::println("脏了以后 size = {}", scores.size());
    std::println("换成 at 读一次新同学: {}", scores.at("新同学"));   // 这一句换成 at 就不会新增
    scores.erase("新同学");                            // 任务 2：删掉误创建的那一条
    std::println("删完 size = {}", scores.size());
    return 0;
}

